steps.script:
GameState.state["factions"]["1"]["detachment"] = "Dread Mob"
StratagemManager.load_faction_stratagems_for_player(1)
GameState.state.players["1"]["cp"] = 1
GameState.state.players["2"]["cp"] = 0
var xs = [37.0, 39.6, 42.2]
var ms = GameState.get_unit("U_KILLA_KANS_A").models
for i in range(ms.size()):
	ms[i]["position"] = {"x": xs[i] * 40.0, "y": 46.6 * 40.0}
var wall := {"id": "ork11e_test_charge_wall", "type": "ruins", "category": "dense", "height_category": "tall", "height": 6.0, "height_inches": 6.0, "piece_class": "feature", "position": Vector2(1560, 1786), "size": Vector2(480, 20), "rotation": 0.0, "traits": [], "polygon": PackedVector2Array([Vector2(1320, 1776), Vector2(1800, 1776), Vector2(1800, 1796), Vector2(1320, 1796)])}
TerrainManager.terrain_features.append(wall)
TerrainManager.terrain_loaded.emit(TerrainManager.terrain_features)
var ph = PhaseManager.get_current_phase_instance()
ph.game_state_snapshot = GameState.create_snapshot()
tree.root.get_node("Main")._recreate_unit_visuals()
return RulesEngine.is_unit_engaged("U_KILLA_KANS_A", GameState.state)

var kw = GameState.get_unit("U_KILLA_KANS_A").meta.keywords
var a = Vector2(37.0 * 40.0, 46.6 * 40.0)
var b = Vector2(36.9 * 40.0, 40.6 * 40.0)
var plain = TerrainManager.calculate_charge_terrain_penalty(a, b, false, kw)
var mobile = TerrainManager.calculate_charge_terrain_penalty(a, b, false, kw + ["MOBILE"])
return "%.1f|%.1f" % [plain, mobile]

var cc = tree.root.get_node("Main").charge_controller
var out = []
for i in range(cc.unit_selector.get_item_count()):
	out.append(str(cc.unit_selector.get_item_metadata(i)))
return out.find("U_KILLA_KANS_A")

var cc = tree.root.get_node("Main").charge_controller
var out = []
for i in range(cc.target_list.get_item_count()):
	out.append(str(cc.target_list.get_item_metadata(i)))
return ",".join(out)

var ph = PhaseManager.get_current_phase_instance()
var pc = ph.pending_charges.get("U_KILLA_KANS_A", {})
var cc = tree.root.get_node("Main").charge_controller
print("[ork11e SJ charge] pending charge after roll: ", pc, " awaiting_movement=", cc.awaiting_movement)
if not pc.has("distance"):
	return "FAILED_CHARGE:" + str(pc)
return int(pc["distance"]) == 9 and pc.get("targets", []) == ["U_CUSTODIAN_GUARD_E"] and cc.awaiting_movement
